/* Shared workspace behavior. All records remain scoped to the signed-in account. */
(() => {
  'use strict';
  const A = globalThis.DraftmangoAccounts, M = globalThis.DraftmangoModel;
  const e = M.escapeHtml, $ = s => document.querySelector(s);
  const paths = {chat:'M4 4h16v12H9l-5 4V4Z',folder:'M3 7V4h7l2 3h9v13H3Z',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-5-5 5 5-5 5',up:'M12 20V4m-6 6 6-6 6 6',menu:'M4 6h16M4 12h16M4 18h16',sliders:'M5 3v6m0 4v8M12 3v11m0 4v3m7-18v3m0 4v11M2 9h6m1 5h6m1-8h6',home:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',more:'M5 12h.01M12 12h.01M19 12h.01',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',external:'M6 18 18 6M7 6h11v11',file:'M6 3h8l4 4v14H6ZM14 3v5h4',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 17V3m-5 5 5-5 5 5M4 17v4h16v-4',monitor:'M3 4h18v13H3ZM8 21h8M12 17v4',terminal:'m5 7 5 5-5 5m8 0h6',lock:'M5 10h14v11H5ZM8 10V7a4 4 0 0 1 8 0v3',user:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0M4 21v-2a8 8 0 0 1 16 0v2',link:'m9 15 6-6M8 17l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m1-1 1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',chart:'M4 3v18h17M9 17V9m5 8V5m5 12v-7',credit:'M3 5h18v14H3ZM3 9h18M7 15h3',database:'M3 6c0-5 18-5 18 0v12c0 5-18 5-18 0ZM3 6c0 5 18 5 18 0M3 12c0 5 18 5 18 0',check:'m5 12 4 4L19 6',search:'M16 16l5 5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',history:'M3 3v6h6M3 9a9 9 0 1 1 1 10M12 7v5l3 2',play:'m7 4 14 8-14 8Z',test:'m9 3 3 3-8 12a2 2 0 0 0 3 3L19 9l3 3M8 14l5 5',save:'M4 3h14l3 3v15H3V3ZM7 3v6h10V3M7 21v-8h10v8',expand:'M3 9V3h6m6 0h6v6M3 15v6h6m6 0h6v-6',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',code:'m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c-6 5-6 13 0 18 6-5 6-13 0-18',copy:'M8 8h13v13H8ZM16 8V3H3v13h5',sound:'M3 9h4l5-5v16l-5-5H3ZM16 8c3 2 3 6 0 8M19 5c5 4 5 10 0 14'};
  const icon = name => name==='more'?'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1.7" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1.7" fill="currentColor" stroke="none"/><circle cx="19" cy="12" r="1.7" fill="currentColor" stroke="none"/></svg>':`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
  const defaults = {theme:'light',sound:true,fontSize:14,indent:2,wordWrap:false,lineNumbers:true,reduceMotion:false,device:'responsive',buildLevel:'standard',autoRefresh:true,starter:'auto',color:'auto'};
  let prefs = {...defaults}, profile, activities=[], toastTimer, activeMenu;
  function library(){return M.readStore(localStorage.getItem(A.key('projects'))) || {schema:1,activeId:'',projects:[]};}
  const meta = record => record?.workspace || {};
  const isChat = record => meta(record).kind === 'chat';
  const records = (kind, archived=false) => library().projects.filter(p=>!meta(p).deleted && (!kind || isChat(p)===(kind==='chat')) && !!meta(p).archived===archived).sort((a,b)=>Number(!!meta(b).pinned)-Number(!!meta(a).pinned)||b.updatedAt.localeCompare(a.updatedAt));
  const get = id => library().projects.find(p=>p.id===id && !meta(p).deleted);
  function save(record){const lib=library();const index=lib.projects.findIndex(p=>p.id===record.id);if(index<0)lib.projects.push(record);else lib.projects[index]=record;A.saveLibrary(lib,record.id);window.dispatchEvent(new Event('draftmango:records'));return record;}
  function update(id, fields){const p=get(id);if(!p)throw new Error('This item is no longer available.');return save({...p,...fields,workspace:{...meta(p),...(fields.workspace||{})},updatedAt:new Date().toISOString()});}
  function toast(message){let node=$('#toast');if(!node){node=document.createElement('div');node.id='toast';node.className='toast';node.setAttribute('role','status');document.body.append(node);}node.textContent=message;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,5000);}
  function button(text,action,cls='button'){return `<button type="button" class="${cls}" data-action="${action}">${text}</button>`;}
  function field(label,id,value='',type='text',extra=''){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${e(value)}" ${extra}>`;}
  function dialog(title,content,{submit,label='Save',wide=false}={}){
    closeMenu(); const d=document.createElement('dialog');d.className='ws-dialog'+(wide?' wide':'');d.innerHTML=`<form><header><h2>${e(title)}</h2><button type="button" class="icon-button" aria-label="Close dialog" data-dismiss>${icon('close')}</button></header><div class="dialog-body">${content}</div><p class="dialog-error" role="alert" hidden></p>${submit?`<footer><button type="button" class="button" data-dismiss>Cancel</button><button type="submit" class="button primary">${e(label)}</button></footer>`:''}</form>`;
    document.body.append(d);d.querySelectorAll('[data-dismiss]').forEach(b=>b.onclick=()=>d.close());d.addEventListener('close',()=>d.remove());d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();}});
    d.querySelector('form').onsubmit=async event=>{event.preventDefault();if(!submit)return;const b=d.querySelector('[type=submit]');b.disabled=true;try{await submit(d);if(d.open)d.close();}catch(error){const p=d.querySelector('.dialog-error');p.hidden=false;p.textContent=error.message;}finally{b.disabled=false;}};d.showModal();return d;
  }
  function closeMenu(){activeMenu?.remove();activeMenu=null;}
  function menu(anchor, items){closeMenu();const node=document.createElement('div');node.className='ws-menu';node.setAttribute('role','menu');items.forEach(({label,run,danger=false})=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('role','menuitem');if(danger)b.className='danger';b.onclick=()=>{closeMenu();run();};node.append(b);});document.body.append(node);const r=anchor.getBoundingClientRect();node.style.left=Math.max(8,Math.min(r.left,innerWidth-node.offsetWidth-8))+'px';node.style.top=Math.max(8,Math.min(r.bottom+5,innerHeight-node.offsetHeight-8))+'px';activeMenu=node;node.querySelector('button')?.focus();node.onkeydown=event=>{const buttons=[...node.children],i=buttons.indexOf(document.activeElement);if(['ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();buttons[(i+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}if(event.key==='Escape'){closeMenu();anchor.focus();}};}
  document.addEventListener('pointerdown',event=>{if(activeMenu&&!activeMenu.contains(event.target))closeMenu();});window.addEventListener('resize',closeMenu);
  const legacyEmptyFiles=()=>({'index.html':'<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Untitled project</title>\n<link rel="stylesheet" href="styles.css">\n</head>\n<body>\n<script src="app.js"></script>\n</body>\n</html>','styles.css':'','app.js':''});
  const emptyFiles=()=>globalThis.DraftmangoProject.scaffold();
  function create(kind,title,brief='',parentId=''){
    let p=M.createProject(brief,'custom');p.title=title||'New chat';p.messages=[];p.prompt=brief.slice(0,1200);p.workspace={kind,parentId,brief,folders:[],attachments:[],build:{level:'standard'}};
    const parent=get(parentId);p=M.commitFiles(p,parent?.files||emptyFiles(),'Project created');if(parent)p.designBrief=parent.designBrief;
    save(p);recordActivity('project',p.id);return p;
  }
  const href = p => '/workspace#'+new URLSearchParams({project:p.id});
  function newProject(source){dialog(source?'Save as a project':'Start a new project',`<p>${source?'Keep this chat and its files in a named project. You can start more chats in the same project.':'Set up your project first. Nothing builds until you open it and send a request.'}</p>${field('Project name','new-project-name',source?.title||'','text','required maxlength="60"')}<label for="new-project-brief">Project brief <span class="muted">(optional)</span></label><textarea id="new-project-brief" rows="4" maxlength="3000" placeholder="What are you building, and who is it for?">${e(source?.prompt||'')}</textarea>`,{label:source?'Create project':'Create and open project',submit:d=>{const name=d.querySelector('#new-project-name').value.trim();if(!name)throw new Error('Enter a project name.');let p=create('project',name,d.querySelector('#new-project-brief').value.trim());if(source){p=save({...p,files:source.files,codeDraft:source.codeDraft,history:structuredClone(source.history),cursor:source.cursor,design:source.design,designBrief:source.designBrief});update(source.id,{workspace:{parentId:p.id}});}location.href='/dashboard#project/'+p.id;}});}
  function rename(record){dialog(isChat(record)?'Rename chat':'Rename project',field('Name','record-name',record.title,'text','required maxlength="60"'),{submit:d=>{const title=d.querySelector('#record-name').value.trim();if(!title)throw new Error('Enter a name.');update(record.id,{title});toast('Name saved.');}});}
  function move(record){dialog('Move chat',`<p>Choose the project this conversation belongs to.</p><label for="move-project">Project</label><select id="move-project"><option value="">Standalone chat</option>${records('project').map(p=>`<option value="${e(p.id)}" ${meta(record).parentId===p.id?'selected':''}>${e(p.title)}</option>`).join('')}</select>`,{label:'Move chat',submit:d=>{update(record.id,{workspace:{parentId:d.querySelector('#move-project').value}});toast('Chat moved.');}});}
  function remove(record){dialog(`Delete ${isChat(record)?'chat':'project'}?`,`<p>Delete <strong>${e(record.title)}</strong>${isChat(record)?' and its conversation':' and its related chats'} from your workspace?</p><p>This removes it from your project library. Export a copy first if you need these files.</p>`,{label:'Delete',submit:()=>{for(const p of library().projects.filter(p=>p.id===record.id||meta(p).parentId===record.id))update(p.id,{workspace:{deleted:true}});if(globalThis.DraftmangoEditor?.project.id===record.id)location.href='/dashboard#chats';toast('Deleted from your workspace.');}});}
  function recordMenu(anchor,p){menu(anchor,[{label:meta(p).pinned?'Unpin':'Pin',run:()=>update(p.id,{workspace:{pinned:!meta(p).pinned}})},{label:'Rename',run:()=>rename(p)},...(isChat(p)?[{label:'Move to project',run:()=>move(p)},{label:'Save as project',run:()=>newProject(p)}]:[{label:'Open in editor',run:()=>location.href=href(p)},{label:'Duplicate project',run:()=>{const copy=structuredClone(p);copy.id=crypto.randomUUID();copy.title=(p.title+' copy').slice(0,60);copy.createdAt=copy.updatedAt=new Date().toISOString();save(copy);toast('Project duplicated.');}}]),{label:meta(p).archived?'Restore from archive':'Archive',run:()=>update(p.id,{workspace:{archived:!meta(p).archived}})},{label:'Delete',danger:true,run:()=>remove(p)}]);}
  function sidebar(root,current='home',activeId=''){
    if(!root)return;
    const nav=[['home','home','Workspace'],['chats','chat','Chats'],['new-project','plus','New project'],['projects','folder','Your projects'],['domains','globe','Domains'],['settings/profile','sliders','Settings']];
    root.innerHTML=`<div class="ws-brand-row"><a href="/dashboard" class="brand" aria-label="Draftmango workspace"><svg class="brand-mark"><use href="#mango"/></svg><span>draftmango.</span></a><button class="icon-button ws-nav-close" aria-label="Close navigation">${icon('close')}</button></div><a class="button ws-new-chat" href="/dashboard#new">${icon('plus')}New chat</a><nav class="ws-nav" aria-label="Main navigation">${nav.map(([route,symbol,label])=>`<a href="/dashboard#${route}" ${current===route.split('/')[0]?'aria-current="page"':''}>${icon(symbol)}${label}</a>`).join('')}</nav><div class="ws-recents">${['chat','project'].map(kind=>`<section><h2>Recent ${kind}s</h2>${records(kind).slice(0,6).map(p=>`<div class="ws-recent ${p.id===activeId?'is-active':''}"><a href="${kind==='chat'?href(p):'/dashboard#project/'+p.id}" title="${e(p.title)}">${icon(kind==='chat'?'chat':'folder')}<span>${e(p.title)}</span></a><button class="icon-button" data-record-menu="${e(p.id)}" aria-label="Manage ${kind} ${e(p.title)}">${icon('more')}</button></div>`).join('')||`<p class="ws-empty-note">${kind==='chat'?'Your recent conversations appear here.':'Create a project to organise files and related chats.'}</p>`}</section>`).join('')}</div><div class="ws-sidebar-bottom"><div class="ws-bottom-links"><a href="/help">Help &amp; support ${icon('external')}</a><a href="/legal#privacy">Privacy</a></div><div class="ws-bottom-links"><a href="/">Back to Draftmango ${icon('external')}</a><button class="icon-button" data-theme-toggle aria-label="Switch to ${document.documentElement.dataset.theme==='dark'?'light':'dark'} mode">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button></div><a class="account-link" href="/dashboard#settings/profile"><span class="avatar">${e((profile?.name||A.user?.email||'D').slice(0,1).toUpperCase())}</span><span><strong>${e(profile?.name||A.user?.email||'Your account')}</strong><small>Account settings</small></span>${icon('sliders')}</a></div>`;
    root.querySelector('[href$="#new-project"]').onclick=event=>{event.preventDefault();newProject();};root.querySelectorAll('[data-record-menu]').forEach(b=>b.onclick=()=>recordMenu(b,get(b.dataset.recordMenu)));
    root.querySelector('[data-theme-toggle]').onclick=()=>savePrefs({theme:document.documentElement.dataset.theme==='dark'?'light':'dark'}).catch(error=>toast(error.message));
    root.querySelector('.ws-nav-close').onclick=()=>{root.classList.remove('is-open');document.querySelectorAll('.sidebar-scrim,.navigation-scrim').forEach(n=>n.hidden=true);document.querySelector('.workspace-layout')?.removeAttribute('inert');if(root.classList.contains('project-sidebar')){root.inert=innerWidth<=1000;const toggle=document.querySelector('#toggle-navigation');toggle?.setAttribute('aria-expanded','false');toggle?.focus();}};
  }
  function applyPrefs(){const dark=prefs.theme==='dark'||(prefs.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.reduceMotion=String(prefs.reduceMotion);document.documentElement.style.setProperty('--editor-font',prefs.fontSize+'px');document.documentElement.style.setProperty('--editor-indent',prefs.indent);document.documentElement.dataset.editorWrap=String(prefs.wordWrap);document.documentElement.dataset.lineNumbers=String(prefs.lineNumbers);window.dispatchEvent(new Event('draftmango:preferences'));}
  async function savePrefs(changes){const result=await A.request('/api/accounts/profile',{method:'PATCH',body:{preferences:changes}});prefs={...defaults,...result.preferences};profile=result.user;localStorage.setItem(A.key('preferences'),JSON.stringify({...prefs,name:profile.name}));applyPrefs();return prefs;}
  async function init(){try{const cache=JSON.parse(localStorage.getItem(A.key('preferences'))||'{}');prefs={...defaults,...cache};}catch{}profile=A.user;applyPrefs();try{const result=await A.request('/api/accounts/profile');profile=result.user;prefs={...prefs,...result.preferences};if(profile.name) prefs.name=profile.name;localStorage.setItem(A.key('preferences'),JSON.stringify(prefs));applyPrefs();}catch(error){toast('Account preferences could not sync. Your device preferences are available.');}}
  async function recordActivity(kind,projectId,success=true){const event={id:crypto.randomUUID(),kind,projectId,success,at:new Date().toISOString()};activities.unshift(event);try{const result=await A.request('/api/accounts/activity',{method:'POST',body:event});activities=result.activity;}catch{/* Reporting never blocks editing or changes billing. */}}
  async function loadActivity(){const result=await A.request('/api/accounts/activity');activities=result.activity;return activities;}
  function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{dialog('Copy link',field('Link','copy-value',text,'text','readonly'));}}
  function chime(){try{const ctx=new AudioContext();const gain=ctx.createGain();gain.connect(ctx.destination);gain.gain.setValueAtTime(.08,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.6);[660,880].forEach((freq,i)=>{const o=ctx.createOscillator();o.frequency.value=freq;o.connect(gain);o.start(ctx.currentTime+i*.15);o.stop(ctx.currentTime+.6);});setTimeout(()=>ctx.close(),800);}catch{toast('Sound is unavailable in this browser.');}}
  function unavailable(title,copyText){dialog(title,`<p>${e(copyText)}</p><div class="ws-callout">Your existing work is unchanged.</div><footer><button type="button" class="button primary" data-dismiss>Done</button></footer>`);}
  function buildSettings(record,callback){const settings={level:'standard',starter:prefs.starter,color:prefs.color,...meta(record).build};const d=dialog('Build settings',`<label for="build-level">Build level</label><select id="build-level"><option value="standard">Standard</option></select><p class="muted">Your preferred approach for this project. Standard uses the configured Draftmango model.</p><h3>Task preferences</h3><label for="task-budget">Task budget <span class="muted">credits</span></label><input id="task-budget" type="number" min="1" value="5" disabled><p class="muted">Credit budgets become available when metered billing is connected. API usage currently goes to your configured provider.</p><label class="ws-toggle"><span>Run tests in Modal</span><input type="checkbox" disabled></label><p class="muted">Cloud test execution is not connected. Browser source checks and unit tests are available in the editor.</p><details><summary>Draftmango starting style</summary><label for="ws-starter">Starting layout</label><select id="ws-starter">${['auto','custom','cafe','portfolio','store'].map(v=>`<option value="${v}" ${v===settings.starter?'selected':''}>${({auto:'Choose from my idea',custom:'Blank starter',cafe:'Café & hospitality',portfolio:'Portfolio & studio',store:'Store & collection'})[v]}</option>`).join('')}</select><label for="ws-color">Color palette</label><select id="ws-color">${['auto',...Object.keys(M.palettes)].map(v=>`<option value="${v}" ${v===settings.color?'selected':''}>${e(M.palettes[v]?.name||'Match the idea')}</option>`).join('')}</select></details><h3>Your workspace</h3><ul class="ws-feature-list"><li>Code & live preview</li><li>Saved project history</li><li>Download your code</li></ul><div class="ws-callout"><strong>Make a great first brief</strong><p>Describe who it’s for, what it should do, and the look you have in mind. Add a screenshot or existing code if you have it.</p></div>`,{label:'Save settings',submit:d=>{const next={level:'standard',starter:d.querySelector('#ws-starter').value,color:d.querySelector('#ws-color').value};if(record)update(record.id,{workspace:{build:next}});callback?.(next);}});d.classList.add('ws-drawer');return d;}
  function filePicker({images=false,multiple=true,accept,onFiles}){const input=document.createElement('input');input.type='file';input.multiple=multiple;input.accept=accept|| (images?'image/png,image/jpeg,image/webp,image/gif':'.txt,.md,.html,.css,.js,.ts,.json,.csv,.pdf');input.onchange=()=>onFiles([...input.files]);input.click();}
  async function references(files,existing=[]){if(existing.length+files.length>5)throw new Error('Use up to 5 references at a time.');if(existing.reduce((sum,r)=>sum+(r.size||new TextEncoder().encode(r.data).length),0)+files.reduce((sum,f)=>sum+f.size,0)>2*1024*1024)throw new Error('Use references up to 2 MB combined.');const output=[...existing];for(const file of files){if(file.size>1024*1024)throw new Error(file.name+' exceeds the 1 MB reference limit.');const binary=/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.type==='application/pdf';const data=binary?await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);}):await file.text();output.push({name:file.name.slice(0,150),type:binary?file.type:'text/plain',data,size:file.size});}return output;}
  function attachmentMenu(anchor,onFiles,onNotes){menu(anchor,[{label:'Add files · Code, documents, text or PDFs',run:()=>filePicker({onFiles})},{label:'Add images · Screenshots, inspiration and designs',run:()=>filePicker({images:true,onFiles})},{label:'Import from GitHub',run:githubImport},...(onNotes?[{label:'Add project notes',run:onNotes}]:[])]);}
  function githubImport(){const d=dialog('Import from GitHub',`<p>Select a repository to open its source in a new editor project.</p><p>Public repositories can be imported now. Private repository access needs a GitHub App connection.</p>${field('Public repository','github-repository','','url','required placeholder="https://github.com/owner/repository"')}<p class="muted">Imports source files only. No code runs on the server.</p><button type="button" class="button" id="github-connect">Connect GitHub</button>`,{label:'Import repository',submit:async d=>{const result=await A.request('/api/accounts/import-github',{method:'POST',body:{url:d.querySelector('#github-repository').value}});let p=create('project',result.name);p=M.commitFiles(p,result.files,'Imported from GitHub');save(p);location.href=href(p);}});d.querySelector('#github-connect').onclick=()=>unavailable('Connect GitHub','A Draftmango GitHub App has not been configured yet. You can import a public repository or upload source files while private access is being set up.');}
  globalThis.DraftmangoWorkspace={e,icon,$,button,field,defaults,init,library,records,get,meta,isChat,save,update,create,href,emptyFiles,toast,dialog,menu,closeMenu,newProject,rename,move,remove,recordMenu,sidebar,applyPrefs,savePrefs,recordActivity,loadActivity,download,copy,chime,unavailable,buildSettings,filePicker,references,attachmentMenu,githubImport,get preferences(){return prefs;},get profile(){return profile;},set profile(v){profile=v;},get activity(){return activities;}};
})();
